import React, { useEffect, useState } from "react";
import axios from "axios";
import { FaBookMedical, FaClipboardList, FaPlusCircle } from "react-icons/fa";
import AlertBox from "./AlertBox";

function TeacherDashboard() {
  const teacherId = localStorage.getItem("user_id");

  const [formData, setFormData] = useState({
    title: "",
    description: "",
    subject_code: ""
  });

  const [courses, setCourses] = useState([]);
  const [alert, setAlert] = useState(null);

  const fetchCourses = async () => {
    try {
      const response = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = response.data.courses || [];
      const myCourses = allCourses.filter(
        (course) => String(course.teacher_id) === String(teacherId)
      );
      setCourses(myCourses);
    } catch (error) {
      console.error("Error fetching courses:", error);
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!teacherId) {
      setAlert({
        message: "Please login as teacher first",
        type: "error"
      });
      return;
    }

    try {
      const payload = {
        ...formData,
        teacher_id: parseInt(teacherId)
      };

      const response = await axios.post(
        "http://127.0.0.1:8000/create-course",
        payload
      );

      setAlert({
        message: response.data.message,
        type: "success"
      });

      setFormData({
        title: "",
        description: "",
        subject_code: ""
      });

      fetchCourses();
    } catch (error) {
      console.error(error);
      setAlert({
        message: "Course creation failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2 style={{ color: "#4a148c", marginBottom: "20px" }}>
        Teacher Dashboard
      </h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "25px"
        }}
      >
        <div
          style={{
            background: "#f9f5ff",
            borderRadius: "16px",
            padding: "20px",
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
          }}
        >
          <h3
            style={{
              display: "flex",
              alignItems: "center",
              gap: "10px",
              color: "#6a1b9a",
              marginBottom: "18px"
            }}
          >
            <FaBookMedical />
            Add New Course
          </h3>

          <form
            onSubmit={handleSubmit}
            style={{
              display: "flex",
              flexDirection: "column",
              gap: "14px"
            }}
          >
            <input
              type="text"
              name="title"
              placeholder="Course Title"
              value={formData.title}
              onChange={handleChange}
              style={{
                padding: "12px",
                borderRadius: "10px",
                border: "1px solid #ccc",
                outline: "none"
              }}
            />

            <input
              type="text"
              name="description"
              placeholder="Course Description"
              value={formData.description}
              onChange={handleChange}
              style={{
                padding: "12px",
                borderRadius: "10px",
                border: "1px solid #ccc",
                outline: "none"
              }}
            />

            <input
              type="text"
              name="subject_code"
              placeholder="Subject Code"
              value={formData.subject_code}
              onChange={handleChange}
              style={{
                padding: "12px",
                borderRadius: "10px",
                border: "1px solid #ccc",
                outline: "none"
              }}
            />

            <button
              type="submit"
              style={{
                background: "#7b1fa2",
                color: "white",
                border: "none",
                padding: "12px",
                borderRadius: "10px",
                fontWeight: "bold",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                gap: "8px"
              }}
            >
              <FaPlusCircle />
              Add Course
            </button>
          </form>
        </div>

        <div
          style={{
            background: "#fff",
            borderRadius: "16px",
            padding: "20px",
            boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
          }}
        >
          <h3
            style={{
              display: "flex",
              alignItems: "center",
              gap: "10px",
              color: "#6a1b9a",
              marginBottom: "18px"
            }}
          >
            <FaClipboardList />
            My Added Courses
          </h3>

          {courses.length === 0 ? (
            <p>No courses added yet.</p>
          ) : (
            courses.map((course) => (
              <div
                key={course.id}
                style={{
                  border: "1px solid #eee",
                  borderRadius: "12px",
                  padding: "14px",
                  marginBottom: "12px",
                  background: "#fafafa"
                }}
              >
                <h4 style={{ marginBottom: "6px", color: "#333" }}>
                  {course.title}
                </h4>
                <p style={{ marginBottom: "6px", color: "#555" }}>
                  {course.description}
                </p>
                <p style={{ margin: 0 }}>
                  <strong>Subject Code:</strong> {course.subject_code}
                </p>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default TeacherDashboard;
